import z3

# Parameters
num_weeks = 5
num_golfers = 24
num_groups = 8
group_size = 3

# Variables: x[w][p] group of golfer p in week w (0..7)
x = [[z3.Int(f"x_{w}_{p}") for p in range(num_golfers)] for w in range(num_weeks)]

solver = z3.Solver()

# Domain constraints
for w in range(num_weeks):
    for p in range(num_golfers):
        solver.add(x[w][p] >= 0, x[w][p] < num_groups)

# Each week, exactly 3 golfers per group
for w in range(num_weeks):
    for g in range(num_groups):
        solver.add(sum([z3.If(x[w][p] == g, 1, 0) for p in range(num_golfers)]) == group_size)

# No pair of golfers in same group more than once
for p1 in range(num_golfers):
    for p2 in range(p1+1, num_golfers):
        # Count how many weeks they are in same group
        same_group_count = sum([z3.If(x[w][p1] == x[w][p2], 1, 0) for w in range(num_weeks)])
        solver.add(same_group_count <= 1)

print("Solving...")
result = solver.check()
print(f"Result: {result}")

if result == z3.sat:
    model = solver.model()
    solution = []
    for w in range(num_weeks):
        for p in range(num_golfers):
            solution.append(model.evaluate(x[w][p]).as_long())
    print("Solution:", solution)
    # Verify
    # Check group sizes per week
    ok = True
    for w in range(num_weeks):
        counts = [0]*num_groups
        for p in range(num_golfers):
            counts[solution[w*num_golfers + p]] += 1
        if any(c != group_size for c in counts):
            print(f"Week {w} group sizes wrong: {counts}")
            ok = False
    # Check pair repeats
    for p1 in range(num_golfers):
        for p2 in range(p1+1, num_golfers):
            count = 0
            for w in range(num_weeks):
                if solution[w*num_golfers + p1] == solution[w*num_golfers + p2]:
                    count += 1
            if count > 1:
                print(f"Pair ({p1},{p2}) repeats {count} times")
                ok = False
    if ok:
        print("Verification passed")
else:
    print("UNSAT")
